CREATE OR REPLACE FUNCTION poems_search_vec_trg() RETURNS trigger AS $$
DECLARE aname text; trans text;
BEGIN
  SELECT name INTO aname FROM authors WHERE id = NEW.author_id;
  SELECT string_agg(content, ' ') INTO trans
    FROM poem_translations WHERE poem_id = NEW.id AND is_deleted = false;
  NEW.search_vec :=
    setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.name, ''))), 'A') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(aname, ''))), 'B') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.content, ''))), 'C') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.transliteration, ''))), 'D') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(NEW.meaning, ''))), 'D') ||
    setweight(to_tsvector('simple', f_unaccent(coalesce(trans, ''))), 'D');
  RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION poem_translations_refresh_search() RETURNS trigger AS $$
DECLARE pid bigint;
BEGIN
  pid := COALESCE(NEW.poem_id, OLD.poem_id);
  UPDATE poems p SET search_vec =
      setweight(to_tsvector('simple', f_unaccent(coalesce(p.name, ''))), 'A') ||
      setweight(to_tsvector('simple', f_unaccent(coalesce((SELECT name FROM authors WHERE id = p.author_id), ''))), 'B') ||
      setweight(to_tsvector('simple', f_unaccent(coalesce(p.content, ''))), 'C') ||
      setweight(to_tsvector('simple', f_unaccent(coalesce(p.transliteration, ''))), 'D') ||
      setweight(to_tsvector('simple', f_unaccent(coalesce(p.meaning, ''))), 'D') ||
      setweight(to_tsvector('simple', f_unaccent(coalesce(
        (SELECT string_agg(content, ' ') FROM poem_translations WHERE poem_id = p.id AND is_deleted = false), ''))), 'D')
    WHERE p.id = pid;
  RETURN NULL;
END $$ LANGUAGE plpgsql;
